// ── 에러 자동 기록 (error_logs 테이블로 전송) ──
// 앱에서 예상 못한 에러가 나면 조용히 Supabase에 기록한다.
// 조합원은 아무것도 안 해도 되고, 희태님은 SQL Editor에서 모아 본다.
let _lastErrLog = 0;
async function logError(info: any) {
  try {
    // 같은 에러가 쏟아질 때 1초에 1건만 (스팸/무한루프 방지)
    const now = Date.now();
    if (now - _lastErrLog < 1000) return;
    _lastErrLog = now;
    await supabase.from("error_logs").insert([
      {
        user_id: info.userId ?? null,
        user_name: info.userName ?? null,
        screen: info.screen ?? null,
        message: String(info.message ?? "").slice(0, 2000),
        stack: info.stack ? String(info.stack).slice(0, 4000) : null,
        user_agent: typeof navigator !== "undefined" ? navigator.userAgent : null,
        page_url: typeof location !== "undefined" ? location.href : null,
      },
    ]);
  } catch (e) {
    // 로깅 자체가 실패해도 앱은 계속 동작 (조용히 무시)
  }
}

// ── 토스트 알림 (화면 아래에서 떴다가 자동으로 사라짐) ──
// 어디서든 showToast("메시지") 또는 showToast("실패", "error") 로 호출.
// 사용자 시간대(한국) 기준 오늘 날짜 YYYY-MM-DD.
// 주의: new Date().toISOString()은 UTC 기준이라 한국 아침 9시 전엔 "어제"가 나옴 (검증된 버그)
function todayLocalStr(): string {
  const t = new Date();
  return `${t.getFullYear()}-${String(t.getMonth() + 1).padStart(2, "0")}-${String(t.getDate()).padStart(2, "0")}`;
}

function showToast(message: string, type: "success" | "error" = "success") {
  try {
    window.dispatchEvent(
      new CustomEvent("ml-toast", { detail: { message, type } })
    );
  } catch (e) {}
}

// ── 교번 배열 개정판 선택 ──
// schedule_rotation에 적용일(effective_date)이 다른 여러 판이 있을 때,
// 그 날짜에 적용되는 판(적용일 <= 날짜 중 가장 최신)을 고른다.
// 적용일이 없는 옛 데이터는 원본 판("2026-06-01")으로 취급 → SQL 실행 전에도 안전.
const ROTATION_BASE_DATE = "2026-06-01";
function pickRotationVersion(rotationData: any[], groupName: string, dateStr: string): string {
  let ver = "";
  let earliest = "";
  for (const r of rotationData) {
    if (r.group_name !== groupName) continue;
    const ed = String(r.effective_date || ROTATION_BASE_DATE).slice(0, 10);
    if (!earliest || ed < earliest) earliest = ed;
    if (ed <= dateStr && ed > ver) ver = ed;
  }
  // 날짜가 모든 판보다 이전이면 가장 오래된 판 사용
  return ver || earliest;
}

// ── 교번 근무 계산 (공용 함수) ──
// member, date, rotationData만 있으면 계산되는 순수 함수.
// 근무표·교번교체가 똑같이 이걸 써서 결과가 절대 어긋나지 않음.
// ── 공휴일 캐시 (글로벌) ──
//   read-holidays는 Netlify 함수라 처음 부를 때 깨우는 시간(콜드스타트)이 걸림.
//   같은 해는 앱이 켜 있는 동안 한 번만 부르고 재사용. (요청 자체를 저장해 동시 호출도 1번으로 합침)
const _holCache = new Map<number, Promise<string[]>>();
function fetchHolidays(year: number): Promise<string[]> {
  if (!_holCache.has(year)) {
    const lsKey = "holidays_" + year;
    // 저장해둔 목록이 있으면 먼저 꺼냄 (하루 이내면 그대로 씀 → 기다림 없이 바로 빨간날 표시)
    let saved: string[] = [];
    let savedAt = 0;
    try {
      const raw = localStorage.getItem(lsKey);
      if (raw) {
        const j = JSON.parse(raw);
        if (Array.isArray(j.list)) { saved = j.list; savedAt = Number(j.at) || 0; }
      }
    } catch (e) {}
    const fresh = fetch("/.netlify/functions/read-holidays?year=" + year)
      .then((r) => r.json())
      .then((j: any) => {
        const list: string[] = j && j.holidays ? j.holidays : [];
        if (list.length > 0) {
          try { localStorage.setItem(lsKey, JSON.stringify({ list, at: Date.now() })); } catch (e) {}
          _holCache.set(year, Promise.resolve(list));
          return list;
        }
        return saved;
      })
      .catch(() => saved);
    const oneDay = 24 * 60 * 60 * 1000;
    const usable = saved.length > 0 && Date.now() - savedAt < oneDay;
    _holCache.set(year, usable ? Promise.resolve(saved) : fresh);
  }
  return _holCache.get(year)!;
}

// ── 교대 4조 근무 계산 (글로벌) ──
//   패턴: 주간 → 야간 → 비번 → 휴무 (4일 반복, 휴무는 번호 없음)
//   앵커: 2026-07-15 → A조 주간 · B조 휴무 · C조 비번 · D조 야간
const SHIFT_PATTERN = ["주간", "야간", "비번", "휴무"];
const SHIFT_OFFSET: Record<string, number> = { A: 0, D: 1, C: 2, B: 3 };
function calcShiftWork(team: any, date: Date): string {
  const off = SHIFT_OFFSET[String(team || "").trim().toUpperCase()];
  if (off === undefined) return "";
  const anchor = new Date(2026, 6, 15);
  const d = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  const days = Math.round((d.getTime() - anchor.getTime()) / 86400000);
  const idx = (((days + off) % 4) + 4) % 4;
  return SHIFT_PATTERN[idx];
}

function calcKyobunWork(member: any, date: Date, rotationData: any[], swapData: any[] = [], allMembers: any[] = [], startHistory: any[] = []) {
  if (!member || rotationData.length === 0) return null;

  const calc = (mem: any) => {
    if (!mem) return null;
    const groupName = mem.work_group === "도봉" ? "도봉 41" : "대공원 114";
    const base = new Date("2026-06-01");
    base.setHours(0, 0, 0, 0);
    const target = new Date(date);
    target.setHours(0, 0, 0, 0);
    const diff = Math.round((target.getTime() - base.getTime()) / 86400000);
    // B안: 날짜별 시작점 이력 반영 (이력 없으면 원본 그대로)
    let effStart = mem.start_position;
    if (startHistory.length > 0 && mem.id != null) {
      const _yy = target.getFullYear();
      const _mo = String(target.getMonth() + 1).padStart(2, "0");
      const _da = String(target.getDate()).padStart(2, "0");
      const _dStr = `${_yy}-${_mo}-${_da}`;
      const _hit = startHistory
        .filter((h) => String(h.member_id) === String(mem.id) && h.effective_date <= _dStr)
        .sort((a, b) => (a.effective_date < b.effective_date ? 1 : -1))[0];
      if (_hit) effStart = _hit.start_position;
    }
    const pos =
      ((((effStart - 1 + diff) % mem.schedule_total) +
        mem.schedule_total) %
        mem.schedule_total) +
      1;
    const _vy = target.getFullYear();
    const _vm = String(target.getMonth() + 1).padStart(2, "0");
    const _vd = String(target.getDate()).padStart(2, "0");
    const _rotVer = pickRotationVersion(rotationData, groupName, `${_vy}-${_vm}-${_vd}`);
    const row = rotationData.find(
      (r) =>
        r.group_name === groupName &&
        String(r.effective_date || ROTATION_BASE_DATE).slice(0, 10) === _rotVer &&
        r.position === pos
    );
    return row ? { dia: row.dia_value, type: row.work_type } : null;
  };

  const mine = calc(member);

  // 교체기록·조합원 목록이 넘어왔을 때만 교체 반영 (없으면 기존과 100% 동일)
  if (swapData.length > 0 && allMembers.length > 0 && member.employee_number != null) {
    const y = date.getFullYear();
    const mm = String(date.getMonth() + 1).padStart(2, "0");
    const dd = String(date.getDate()).padStart(2, "0");
    const dateStr = `${y}-${mm}-${dd}`;
    const emp = String(member.employee_number);
    const swap = swapData.find(
      (s) =>
        s.swap_date <= dateStr &&
        (s.swap_end || s.swap_date) >= dateStr &&
        (String(s.a_employee_number) === emp ||
          String(s.b_employee_number) === emp)
    );
    if (swap) {
      const partnerEmp =
        String(swap.a_employee_number) === emp
          ? String(swap.b_employee_number)
          : String(swap.a_employee_number);
      const partner = allMembers.find(
        (p) => String(p.employee_number) === partnerEmp
      );
      if (partner) {
        const partnerWork = calc(partner);
        if (partnerWork) return { ...partnerWork, swapped: true };
      }
    }
  }

  return mine;
}
function calcTongsangWork(member: any, date: Date, holidays: string[] = []) {
  if (!member || !member.tongsang_base_date || member.tongsang_base_dia == null) return null;
  const isOff = (d: Date) => {
    const day = d.getDay();
    if (day === 0 || day === 6) return true;
    const yy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, "0");
    const dd = String(d.getDate()).padStart(2, "0");
    return (holidays || []).includes(`${yy}-${mm}-${dd}`);
  };
  const target = new Date(date);
  target.setHours(0, 0, 0, 0);
  if (isOff(target)) return null;
  const base = new Date(member.tongsang_base_date);
  base.setHours(0, 0, 0, 0);
  let steps = 0;
  const cur = new Date(base);
  if (target.getTime() >= base.getTime()) {
    while (cur.getTime() < target.getTime()) {
      cur.setDate(cur.getDate() + 1);
      if (!isOff(cur)) steps++;
    }
  } else {
    while (cur.getTime() > target.getTime()) {
      cur.setDate(cur.getDate() - 1);
      if (!isOff(cur)) steps--;
    }
  }
  const baseIdx = Number(member.tongsang_base_dia) - 51;
  const idx = (((baseIdx + steps) % 4) + 4) % 4;
  return { dia: 51 + idx, type: "주간" };
}

// ── 월급날 계산 ──
// 매월 20일 지급. 단 20일이 휴일(토·일·공휴일)이면 직전 평일로 앞당김
// (20일 휴일→19일, 19일도 휴일→18일 ...).
function getCachedHolidays(year: number): string[] {
  // 홈 화면이 localStorage("holidays_연도")에 캐시해둔 공휴일을 동기적으로 읽는다.
  try {
    const raw = localStorage.getItem("holidays_" + year);
    if (raw) return JSON.parse(raw);
  } catch (e) {}
  return [];
}
function getPayday(year: number, month0: number, holidays: string[] = []): Date {
  const isHol = (d: Date) => {
    const day = d.getDay();
    if (day === 0 || day === 6) return true;
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, "0");
    const dd = String(d.getDate()).padStart(2, "0");
    return (holidays || []).includes(`${y}-${m}-${dd}`);
  };
  const d = new Date(year, month0, 20);
  d.setHours(0, 0, 0, 0);
  while (isHol(d)) d.setDate(d.getDate() - 1);
  return d;
}

// ── 급여 표시 기준월 계산 ──
// 오늘이 이번 달 월급날을 '지났으면'(당일 제외) 다음 달 급여로 전환한다.
// 실적 기준월 = 급여월의 전달(1일~말일). 반환 month는 0-based.
// holidays를 안 넘기면 localStorage 캐시에서 자동으로 읽는다.
function getPayContext(today: Date, holidays?: string[]) {
  const t = new Date(today);
  t.setHours(0, 0, 0, 0);
  const hol = holidays && holidays.length > 0 ? holidays : getCachedHolidays(t.getFullYear());
  const thisPayday = getPayday(t.getFullYear(), t.getMonth(), hol);
  const passed = t.getTime() > thisPayday.getTime();
  let payY = t.getFullYear();
  let payM = t.getMonth();
  if (passed) {
    payM += 1;
    if (payM > 11) { payM = 0; payY += 1; }
  }
  let perfY = payY;
  let perfM = payM - 1;
  if (perfM < 0) { perfM = 11; perfY -= 1; }
  return { passed, payday: thisPayday, payYear: payY, payMonth: payM, perfYear: perfY, perfMonth: perfM };
}


function calcHolidayFillHours(diaNo: any, shift: string, dateStr: string, diaTable: any[], holidays: string[]) {
  if (!diaNo || !diaTable || diaTable.length === 0) return { workHours: 0, nightHours: 0 };
  const date = new Date(dateStr);
  const isHol = (d: Date) => {
    const day = d.getDay();
    if (day === 0 || day === 6) return true;
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, "0");
    const dd = String(d.getDate()).padStart(2, "0");
    return (holidays || []).includes(`${y}-${m}-${dd}`);
  };
  let dayType: string;
  if (shift === "야간") {
    const tomo = new Date(date);
    tomo.setDate(tomo.getDate() + 1);
    const th = isHol(date), mh = isHol(tomo);
    if (!th && !mh) dayType = "평평";
    else if (!th && mh) dayType = "평휴";
    else if (th && mh) dayType = "휴휴";
    else dayType = "휴평";
  } else {
    dayType = isHol(date) ? "휴일" : "평일";
  }
  const row = (diaTable || []).find(
    (r: any) => Number(r.dia_no) === Number(diaNo) && r.day_type === dayType
  );
  if (!row) return { workHours: 0, nightHours: 0 };
  return { workHours: Number(row.work_hours) || 0, nightHours: Number(row.night_hours) || 0 };
}
function calcSupportOvertimeHours(diaNo: any, shift: string, dateStr: string, diaTable: any[], holidays: string[]) {
  if (!diaNo || !diaTable || diaTable.length === 0) return 0;
  const date = new Date(dateStr);
  const isHol = (d: Date) => {
    const day = d.getDay();
    if (day === 0 || day === 6) return true;
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, "0");
    const dd = String(d.getDate()).padStart(2, "0");
    return (holidays || []).includes(`${y}-${m}-${dd}`);
  };
  const dayType = shift === "야간" ? "평평" : (isHol(date) ? "휴일" : "평일");
  const row = (diaTable || []).find(
    (r: any) => Number(r.dia_no) === Number(diaNo) && r.day_type === dayType
  );
  if (!row || !row.start_time || !row.end_time) return 0;
  const toHr = (t: any) => {
    const p = String(t).split(":");
    return (Number(p[0]) || 0) + (Number(p[1]) || 0) / 60;
  };
  const START = 8 + 50 / 60;
  const END = 18.5;
  const s = toHr(row.start_time);
  const e = toHr(row.end_time);
  let ot = 0;
  if (s < START) ot += START - s;
  if (e > END) ot += e - END;
  return ot;
}
function calcIncomeTax(monthlyPay: number, familyCount: number, childCount: number) {
  const w = Math.max(Number(monthlyPay) || 0, 0);
  const fam = Math.max(Number(familyCount) || 1, 1);
  const child = Math.max(Number(childCount) || 0, 0);
  if (w <= 0) return 0;
  const y = w * 12;
  const earnDed = y <= 5000000 ? y * 0.7
    : y <= 15000000 ? 3500000 + (y - 5000000) * 0.4
    : y <= 45000000 ? 7500000 + (y - 15000000) * 0.15
    : y <= 100000000 ? 12000000 + (y - 45000000) * 0.05
    : 14750000 + (y - 100000000) * 0.02;
  const earnInc = y - earnDed;
  let sp: number;
  if (fam === 1) {
    sp = y <= 30000000 ? 3100000 + y * 0.04
      : y <= 45000000 ? 3100000 + y * 0.04 - (y - 30000000) * 0.05
      : y <= 70000000 ? 3100000 + y * 0.015
      : 3100000 + y * 0.005;
  } else if (fam === 2) {
    sp = y <= 30000000 ? 3600000 + y * 0.04
      : y <= 45000000 ? 3600000 + y * 0.04 - (y - 30000000) * 0.05
      : y <= 70000000 ? 3600000 + y * 0.02
      : 3600000 + y * 0.01;
  } else {
    const ex = y > 40000000 ? (y - 40000000) * 0.04 : 0;
    sp = y <= 30000000 ? 5000000 + y * 0.07 + ex
      : y <= 45000000 ? 5000000 + y * 0.07 - (y - 30000000) * 0.05
      : y <= 70000000 ? 5000000 + y * 0.05
      : 5000000 + y * 0.03;
  }
  const pension = Math.min(w, 6170000) * 0.045 * 12;
  let base = earnInc - 1500000 * fam - sp - pension;
  if (base < 0) base = 0;
  const tax = base <= 14000000 ? base * 0.06
    : base <= 50000000 ? 840000 + (base - 14000000) * 0.15
    : base <= 88000000 ? 6240000 + (base - 50000000) * 0.24
    : base <= 150000000 ? 15360000 + (base - 88000000) * 0.35
    : 37060000 + (base - 150000000) * 0.38;
  let credit = tax <= 1300000 ? tax * 0.55 : 715000 + (tax - 1300000) * 0.30;
  const limit = y <= 33000000 ? 740000
    : y <= 70000000 ? Math.max(740000 - (y - 33000000) * 0.008, 660000)
    : Math.max(660000 - (y - 70000000) * 0.5, 500000);
  credit = Math.min(credit, limit);
  const yearTax = Math.max(tax - credit, 0);
  let monthTax = yearTax / 12;
  const childCredit = child === 0 ? 0 : child === 1 ? 20830 : child === 2 ? 45830 : 45830 + (child - 2) * 33330;
  monthTax = Math.max(monthTax - childCredit, 0);
  return Math.round(monthTax / 10) * 10;
}
function computeNetPay(input: any) {
  const {
    grade, hobong, workType, checkedItems = {}, manualInputs = {},
    nightCount = 0, salaryTable = [], worktypeSettings = [],
    hfRecords = [], diaTable = [], holidays = [], dedRates = null,
    memberInfo = null, rotationData = [], dutyRecords = [],
    swapData = [], allMembers = [], allowSettings = [], hiddenItems = [],
    startHistory = [],
  } = input;

    const row = salaryTable.find((r: any) => Number(r.hobong) === Number(hobong));
  const basicSalary = row ? (row[`grade_${Number(grade)}`] ?? null) : null;
  if (!basicSalary) return null;

  const longService = hobong >= 25 ? 130000 : hobong >= 20 ? 110000 : hobong >= 15 ? 80000 : hobong >= 10 ? 60000 : hobong >= 5 ? 50000 : 0;
  const gradeSupport = (grade === 6 || grade === 7) ? 30000 : 0;
  const seungmuBojo = (workType === "교번" || memberInfo?.work_type === "교번") ? 20000 : String(workType).includes("4조2교대") ? (grade === 3 ? 110000 : 127000) : (grade === 3 ? 135000 : 165000);
  const wtRates: Record<string, number> = {
    통상: 0.1, 변형통상: 0.108, 변형근무: 0.087,
    "4조2교대(비심야)": 0.0675, "4조2교대(심야)": 0.0635,
    "4조2교대(야간집중)": 0.06, 교번: 0.087,
  };
   const wtSetting = worktypeSettings.find((w) => w.work_type === workType);
  const bojeonRate = (wtSetting && wtSetting.bojeon_rate != null) ? Number(wtSetting.bojeon_rate) : (wtRates[workType] ?? 0);
    const workTypePay = (basicSalary && workType) ? Math.round(basicSalary * bojeonRate) : 0;
  const g7s1 = (salaryTable.find((r: any) => r.hobong === 1)?.grade_7) ?? 0;
  const bojeonGasanPay = memberInfo?.bojeon_gasan ? Math.round(g7s1 * 0.04) : 0;

  const allowanceAmount = (item: string): number => {
    if (!checkedItems[item]) return 0;
    const am = (allowSettings || []).find((x: any) => x.name === item);
    if (am && am.visible === false) return 0;
    if ((hiddenItems || []).includes(item)) return 0;
    if (item === "업무보전수당") return workTypePay + bojeonGasanPay;
    if (item === "장기근속수당") return longService;
    if (item === "직급보조비") return gradeSupport;
    if (item === "승무보조비") return seungmuBojo;

    return manualInputs[item] ?? 0;
  };
    const totalAllowance = Object.keys(checkedItems).reduce((s, item) => s + allowanceAmount(item), 0);
  const tongsangWage = memberInfo?.tongsang_wage != null ? Number(memberInfo.tongsang_wage) : (basicSalary ?? 0) + totalAllowance;
const hourlyWage = tongsangWage > 0 ? tongsangWage / 209 : 0;

  const isKyobun = memberInfo?.work_type === "교번" && (memberInfo?.work_group === "대공원" || memberInfo?.work_group === "도봉");
  let kyobunNightHours = 0;
  if (isKyobun && rotationData.length > 0 && diaTable.length > 0) {
    const n = new Date();
    const { perfYear: yy, perfMonth: mn } = getPayContext(n, holidays);
    const dcount = new Date(yy, mn + 1, 0).getDate();
    const dutyDates = new Set(
      (dutyRecords || [])
        .filter((r: any) => r.work_shift === "야간")
        .map((r: any) => r.work_date)
    );
    for (let i = 1; i <= dcount; i++) {
      const w = calcKyobunWork(memberInfo, new Date(yy, mn, i), rotationData, swapData, allMembers, startHistory);
      if (!w) continue;
      const ds = `${yy}-${String(mn + 1).padStart(2, "0")}-${String(i).padStart(2, "0")}`;
      if (String(w.dia).startsWith("대기")) {
        if (w.type === "야간" && !dutyDates.has(ds)) kyobunNightHours += 4;
      } else if (w.type === "야간" && Number(w.dia) >= 1) {
        kyobunNightHours += calcHolidayFillHours(w.dia, "야간", ds, diaTable, holidays).nightHours;
      }
    }
  }
  const nightHoursPerShift = worktypeSettings.find((w: any) => w.work_type === workType)?.night_hours || 0;
  let dutyNightHours = 0;
  dutyRecords.forEach((rec: any) => {
    if (rec.work_shift !== "야간") return;
    if (rec.is_temp_dia) {
      dutyNightHours += Number(rec.temp_night_hours) || 0;
      return;
    }
    const dm = (rec.memo || "").match(/다이아\s*(\d+)/);
    if (!dm) return;
    dutyNightHours += calcHolidayFillHours(dm[1], "야간", rec.work_date, diaTable, holidays).nightHours;
  });
  const nightTotalHours = (isKyobun ? kyobunNightHours : nightHoursPerShift * nightCount) + dutyNightHours;
  const nightPay = Math.round(hourlyWage * 0.5 * nightTotalHours);

  let hfPaySum = 0;
  hfRecords.forEach((rec: any) => {
    let workHours = 0, nightHours = 0;
    if (rec.is_temp_dia) {
      workHours = Number(rec.temp_work_hours) || 0;
      nightHours = Number(rec.temp_night_hours) || 0;
    } else {
      const m = (rec.memo || "").match(/다이아\s*(\d+)/);
      if (!m) return;
      const hres = calcHolidayFillHours(m[1], rec.work_shift, rec.work_date, diaTable, holidays);
      workHours = hres.workHours;
      nightHours = hres.nightHours;
    }
    if (workHours <= 0) return;
    const within8 = Math.min(workHours, 8);
    const over8 = Math.max(workHours - 8, 0);
    hfPaySum += hourlyWage * (within8 * 1.5 + over8 * 2.0) + hourlyWage * 0.5 * nightHours;
  });
  const holidayFillPay = Math.round(hfPaySum);

  let supportOtHours = 0;
  dutyRecords.forEach((rec: any) => {
    if (rec.adjust_type !== "support") return;
    if (rec.work_shift === "야간") return;
    if (rec.is_temp_dia) {
      const toHr = (t: any) => { const p = String(t).split(":"); return (Number(p[0]) || 0) + (Number(p[1]) || 0) / 60; };
      const s = toHr(rec.temp_start_time), e = toHr(rec.temp_end_time);
      const START = 8 + 50 / 60, END = 18.5;
      let ot = 0;
      if (s < START) ot += START - s;
      if (e > END) ot += e - END;
      supportOtHours += ot;
      return;
    }
    const sm = (rec.memo || "").match(/다이아\s*(\d+)/);
    if (!sm) return;
    supportOtHours += calcSupportOvertimeHours(sm[1], rec.work_shift, rec.work_date, diaTable, holidays);
  });
  const supportPay = Math.round(hourlyWage * supportOtHours * 1.5);

    const grossBase = (basicSalary ?? 0) + totalAllowance;
  const totalGross = grossBase + nightPay + holidayFillPay + supportPay;
  const r = dedRates || {};
  const nationalPension = Math.round(tongsangWage * (r.national_pension ?? 0.045));
  const healthInsurance = Math.round(tongsangWage * (r.health_insurance ?? 0.03545));
  const longTermCare = Math.round(healthInsurance * (r.long_term_care ?? 0.1295));
  const employmentInsurance = Math.round(tongsangWage * (r.employment_insurance ?? 0.009));
  const incomeTax = calcIncomeTax(totalGross, Number(memberInfo?.dependents_count) || 1, Number(memberInfo?.children_count) || 0);
  const localTax = Math.round(incomeTax * (r.local_tax ?? 0.1));
  const unionFee = Math.round((basicSalary ?? 0) * (r.union_fee ?? 0.012));
  const totalDeduction = nationalPension + healthInsurance + longTermCare + employmentInsurance + incomeTax + localTax + unionFee;

  return { netPay: totalGross - totalDeduction, totalGross, totalDeduction, tongsangWage };
}
// 근무조정 기록 → 수당 환산 (computeNetPay의 휴무충당/지원/야간취급 산식과 동일하게 유지할 것)
function estimateAdjustPay(records: any[], hourlyWage: number, diaTable: any[], holidays: string[]) {
  if (!hourlyWage || hourlyWage <= 0) return 0;
  let total = 0;
  let supportOtHours = 0;
  (records || []).forEach((rec: any) => {
    if (rec.adjust_type === "holiday_fill") {
      let workHours = 0, nightHours = 0;
      if (rec.is_temp_dia) {
        workHours = Number(rec.temp_work_hours) || 0;
        nightHours = Number(rec.temp_night_hours) || 0;
      } else {
        const m = (rec.memo || "").match(/다이아\s*(\d+)/);
        if (!m) return;
        const hres = calcHolidayFillHours(m[1], rec.work_shift, rec.work_date, diaTable, holidays);
        workHours = hres.workHours;
        nightHours = hres.nightHours;
      }
      if (workHours <= 0) return;
      const within8 = Math.min(workHours, 8);
      const over8 = Math.max(workHours - 8, 0);
      total += hourlyWage * (within8 * 1.5 + over8 * 2.0) + hourlyWage * 0.5 * nightHours;
      return;
    }
    if (rec.adjust_type === "support") {
      if (rec.work_shift === "야간") return;
      if (rec.is_temp_dia) {
        const toHr = (t: any) => { const p = String(t).split(":"); return (Number(p[0]) || 0) + (Number(p[1]) || 0) / 60; };
        const s = toHr(rec.temp_start_time), e = toHr(rec.temp_end_time);
        const START = 8 + 50 / 60, END = 18.5;
        let ot = 0;
        if (s < START) ot += START - s;
        if (e > END) ot += e - END;
        supportOtHours += ot;
        return;
      }
      const sm = (rec.memo || "").match(/다이아\s*(\d+)/);
      if (!sm) return;
      supportOtHours += calcSupportOvertimeHours(sm[1], rec.work_shift, rec.work_date, diaTable, holidays);
      return;
    }
    if (rec.adjust_type === "standby" || rec.adjust_type === "designated") {
      if (rec.work_shift !== "야간") return;
      let nightHours = 0;
      if (rec.is_temp_dia) {
        nightHours = Number(rec.temp_night_hours) || 0;
      } else {
        const dm = (rec.memo || "").match(/다이아\s*(\d+)/);
        if (!dm) return;
        nightHours = calcHolidayFillHours(dm[1], "야간", rec.work_date, diaTable, holidays).nightHours;
      }
      total += hourlyWage * 0.5 * nightHours;
    }
  });
  const within8s = Math.min(supportOtHours, 8);
  const over8s = Math.max(supportOtHours - 8, 0);
  total += hourlyWage * (within8s * 1.5 + over8s * 2.0);
  return Math.round(total);
}
function getTodayWorkInfo(member: any, rotationData: any[], diaTable: any[], holidays: string[], date = new Date(), swapData: any[] = [], allMembers: any[] = [], startHistory: any[] = []) {
  const work = calcKyobunWork(member, date, rotationData, swapData, allMembers, startHistory);
  if (!work) return null;

  const isHol = (d: Date) => {
    const day = d.getDay();
    if (day === 0 || day === 6) return true;
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, "0");
    const dd = String(d.getDate()).padStart(2, "0");
    return (holidays || []).includes(`${y}-${m}-${dd}`);
  };

  let dayType: string | null = null;
  const tomo = new Date(date);
  tomo.setDate(tomo.getDate() + 1);
  const th = isHol(date), mh = isHol(tomo);
  if (work.type === "주간") dayType = th ? "휴일" : "평일";
  else if (work.type === "야간") {
    if (!th && !mh) dayType = "평평";
    else if (!th && mh) dayType = "평휴";
    else if (th && mh) dayType = "휴휴";
    else dayType = "휴평";
  }

  const diaRow = dayType
    ? (diaTable || []).find(
        (r: any) => Number(r.dia_no) === Number(work.dia) && r.day_type === dayType
      )
    : null;

  return { type: work.type, dia: work.dia, diaRow };
}
