function InquiryWrite({ onBack, onSubmit, user }) {
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async () => {
    if (submitting) return; // 연타 방지
    if (!title.trim() || !content.trim()) {
      showToast("제목과 내용을 입력해주세요.");
      return;
    }
    setSubmitting(true);
    try {
      await onSubmit({ title, content });
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div
      style={{
        maxWidth: 430,
        margin: "0 auto",
        fontFamily: "'Apple SD Gothic Neo', 'Noto Sans KR', sans-serif",
        background: "#F4F3FF",
        minHeight: "100vh",
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "56px 20px 16px",
          background: "#fff",
          borderBottom: "1px solid #F3F4F6",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <button
            onClick={onBack}
            style={{
              background: "none",
              border: "none",
              cursor: "pointer",
              padding: 4,
            }}
          >
            <Icon path="M15 19l-7-7 7-7" color="#1F2937" size={24} />
          </button>
          <span style={{ fontSize: 17, fontWeight: 700, color: "#1F2937" }}>
            문의 작성
          </span>
        </div>
        <button
          onClick={handleSubmit}
          disabled={submitting}
          style={{
            background: submitting
              ? "#A5B4FC"
              : "linear-gradient(135deg, #4F46E5, #6D28D9)",
            color: "#fff",
            border: "none",
            borderRadius: 10,
            padding: "8px 18px",
            fontSize: 14,
            fontWeight: 700,
            cursor: submitting ? "default" : "pointer",
            fontFamily: "inherit",
          }}
        >
          {submitting ? "등록 중..." : "등록"}
        </button>
      </div>
      <div style={{ padding: "20px 16px" }}>
        <div
          style={{
            background: "#EEF0FF",
            borderRadius: 12,
            padding: "12px 16px",
            marginBottom: 16,
            fontSize: 13,
            color: "#4F46E5",
            lineHeight: 1.6,
          }}
        >
          🔒 1:1 문의는 작성자 본인과 지회 집행부(관리자)만 볼 수 있으며, 답변은
          관리자가 작성합니다.
        </div>
        <div
          style={{
            background: "#fff",
            borderRadius: 20,
            padding: "20px",
            boxShadow: "0 2px 12px rgba(79,70,229,0.06)",
          }}
        >
          <div style={{ fontSize: 13, color: "#9CA3AF", marginBottom: 16 }}>
            작성자: <strong style={{ color: "#4F46E5" }}>{user?.name}</strong>
          </div>
          <input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="문의 제목을 입력하세요"
            style={{
              width: "100%",
              padding: "13px 0",
              border: "none",
              borderBottom: "1.5px solid #E5E7EB",
              fontSize: 16,
              fontWeight: 600,
              outline: "none",
              boxSizing: "border-box",
              fontFamily: "inherit",
              color: "#1F2937",
              marginBottom: 16,
            }}
          />
          <textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="문의 내용을 자세히 입력해주세요"
            rows={10}
            style={{
              width: "100%",
              padding: "0",
              border: "none",
              fontSize: 15,
              outline: "none",
              boxSizing: "border-box",
              fontFamily: "inherit",
              color: "#374151",
              lineHeight: 1.8,
              resize: "none",
            }}
          />
        </div>
      </div>
    </div>
  );
}

function InquiryDetail({ inquiry, onBack, user }) {
  const [answers, setAnswers] = useState([]);
  const [newAnswer, setNewAnswer] = useState("");

  useEffect(() => {
    supabase
      .from("inquiry_answers")
      .select("*")
      .eq("inquiry_id", inquiry.id)
      .order("created_at", { ascending: true })
      .then(({ data }) => {
        if (data) setAnswers(data);
      });
  }, [inquiry.id]);

  const handleAnswer = () => {
    if (!newAnswer.trim()) return;
    const payload = {
      inquiry_id: inquiry.id,
      author: "관리자",
      content: newAnswer,
    };
    supabase
      .from("inquiry_answers")
      .insert([payload])
      .select()
      .then(({ data }) => {
        if (data && data[0]) {
          setAnswers([...answers, data[0]]);
          setNewAnswer("");
          supabase
            .from("inquiries")
            .update({ status: "답변완료" })
            .eq("id", inquiry.id)
            .then(() => {});
          fetch("/.netlify/functions/send-push", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              title: "💬 문의 답변",
              message: "문의하신 글에 답변이 달렸어요",
              type: "inquiry",
              url: "/",
              to: String(inquiry.author_emp_id),
            }),
          }).catch(() => {});
        }
      });
  };

  return (
    <div
      style={{
        maxWidth: 430,
        margin: "0 auto",
        fontFamily: "'Apple SD Gothic Neo', 'Noto Sans KR', sans-serif",
        background: "#F4F3FF",
        minHeight: "100vh",
        paddingBottom: 80,
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 12,
          padding: "56px 20px 16px",
          background: "#fff",
          borderBottom: "1px solid #F3F4F6",
        }}
      >
        <button
          onClick={onBack}
          style={{
            background: "none",
            border: "none",
            cursor: "pointer",
            padding: 4,
          }}
        >
          <Icon path="M15 19l-7-7 7-7" color="#1F2937" size={24} />
        </button>
        <span style={{ fontSize: 17, fontWeight: 700, color: "#1F2937" }}>
          문의 상세
        </span>
      </div>
      <div
        style={{ background: "#fff", padding: "24px 20px", marginBottom: 8 }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 8,
            marginBottom: 12,
          }}
        >
          <span
            style={{
              background: inquiry.status === "답변완료" ? "#D1FAE5" : "#FEF3C7",
              color: inquiry.status === "답변완료" ? "#10B981" : "#F59E0B",
              fontSize: 11,
              fontWeight: 700,
              borderRadius: 6,
              padding: "3px 8px",
            }}
          >
            {inquiry.status}
          </span>
        </div>
        <h2
          style={{
            fontSize: 18,
            fontWeight: 800,
            color: "#1F2937",
            lineHeight: 1.4,
            marginBottom: 12,
          }}
        >
          {inquiry.title}
        </h2>
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 8,
            marginBottom: 16,
          }}
        >
          <div
            style={{
              width: 28,
              height: 28,
              borderRadius: "50%",
              background: "#EEF0FF",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <Icon
              path="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"
              color="#4F46E5"
              size={14}
            />
          </div>
          <span style={{ fontSize: 13, fontWeight: 600, color: "#1F2937" }}>
            {inquiry.author}
          </span>
          <span style={{ fontSize: 12, color: "#9CA3AF" }}>{inquiry.date}</span>
        </div>
        <div style={{ height: 1, background: "#F3F4F6", marginBottom: 16 }} />
        <p style={{ fontSize: 15, color: "#374151", lineHeight: 1.8 }}>
          {inquiry.content}
        </p>
      </div>
      <div style={{ background: "#fff", padding: "20px" }}>
        <div
          style={{
            fontSize: 14,
            fontWeight: 700,
            color: "#1F2937",
            marginBottom: 16,
          }}
        >
          답변 <span style={{ color: "#4F46E5" }}>{answers.length}</span>
        </div>

        {answers.length === 0 && (
          <div
            style={{
              textAlign: "center",
              padding: "24px 0",
              color: "#9CA3AF",
              fontSize: 14,
            }}
          >
            아직 답변이 없습니다. 첫 답변을 남겨보세요 😊
          </div>
        )}

        {answers.map((a) => (
          <div
            key={a.id}
            style={{ display: "flex", gap: 12, marginBottom: 16 }}
          >
            <div
              style={{
                width: 32,
                height: 32,
                borderRadius: "50%",
                background: a.author === "관리자" ? "#4F46E5" : "#EEF0FF",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                flexShrink: 0,
              }}
            >
              <Icon
                path="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"
                color={a.author === "관리자" ? "#fff" : "#4F46E5"}
                size={14}
              />
            </div>
            <div
              style={{
                flex: 1,
                background: a.author === "관리자" ? "#EEF0FF" : "#F8F7FF",
                borderRadius: 12,
                padding: "12px 14px",
                border: a.author === "관리자" ? "1px solid #C7D2FE" : "none",
              }}
            >
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  marginBottom: 6,
                }}
              >
                <span
                  style={{
                    fontSize: 13,
                    fontWeight: 700,
                    color: a.author === "관리자" ? "#4F46E5" : "#1F2937",
                  }}
                >
                  {a.author} {a.author === "관리자" && "⚙️"}
                </span>
                <span style={{ fontSize: 11, color: "#9CA3AF" }}>{a.date}</span>
              </div>
              <p
                style={{
                  fontSize: 14,
                  color: "#374151",
                  lineHeight: 1.6,
                  margin: 0,
                }}
              >
                {a.content}
              </p>
            </div>
          </div>
        ))}
        {user?.is_admin ? (
          <div
            style={{
              display: "flex",
              gap: 10,
              marginTop: 16,
              alignItems: "flex-end",
            }}
          >
            <div
              style={{
                width: 32,
                height: 32,
                borderRadius: "50%",
                background: "#EEF0FF",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                flexShrink: 0,
              }}
            >
              <Icon
                path="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"
                color="#4F46E5"
                size={14}
              />
            </div>
            <div
              style={{
                flex: 1,
                background: "#F8F7FF",
                borderRadius: 14,
                padding: "10px 14px",
                display: "flex",
                alignItems: "center",
                gap: 8,
              }}
            >
              <input
                value={newAnswer}
                onChange={(e) => setNewAnswer(e.target.value)}
                placeholder="답변을 입력하세요"
                onKeyDown={(e) => {
                  if (e.key === "Enter") handleAnswer();
                }}
                style={{
                  flex: 1,
                  border: "none",
                  background: "none",
                  fontSize: 14,
                  outline: "none",
                  fontFamily: "inherit",
                  color: "#1F2937",
                }}
              />
              <button
                onClick={handleAnswer}
                style={{
                  background: "#4F46E5",
                  border: "none",
                  borderRadius: 8,
                  width: 32,
                  height: 32,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  cursor: "pointer",
                  flexShrink: 0,
                }}
              >
                <Icon
                  path="M12 19l9 2-9-18-9 18 9-2zm0 0v-8"
                  color="#fff"
                  size={16}
                />
              </button>
            </div>
          </div>
        ) : (
          <div
            style={{
              textAlign: "center",
              padding: "12px",
              background: "#F8F7FF",
              borderRadius: 12,
              fontSize: 13,
              color: "#9CA3AF",
            }}
          >
            답변은 지회 집행부(관리자)가 작성합니다. 조금만 기다려 주세요 🙏
          </div>
        )}
      </div>
    </div>
  );
}

function InquiryList({ onBack, onSelect, onWrite, user }) {
  const [inquiries, setInquiries] = useState([]);
  const myEmpId = String(user?.emp_id || user?.id || "guest");
  const isAdmin = user?.is_admin;

  useEffect(() => {
    supabase
      .from("inquiries")
      .select("*")
      .order("created_at", { ascending: false })
      .then(({ data }) => {
        if (data) {
          const visible = isAdmin
            ? data
            : data.filter((q) => q.author_emp_id === myEmpId);
          setInquiries(visible);
        }
      });
  }, []);

  return (
    <div
      style={{
        maxWidth: 430,
        margin: "0 auto",
        fontFamily: "'Apple SD Gothic Neo', 'Noto Sans KR', sans-serif",
        background: "#F4F3FF",
        minHeight: "100vh",
        paddingBottom: 80,
      }}
    >
      <div
        style={{
          background:
            "linear-gradient(135deg, #3730A3 0%, #4F46E5 50%, #6D28D9 100%)",
         padding: "52px 20px 24px",
          borderRadius: 28,
          position: "sticky",
          top: 0,
          zIndex: 50,
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
          }}
        >
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <button
              onClick={onBack}
              style={{
                background: "rgba(255,255,255,0.15)",
                border: "none",
                borderRadius: "50%",
                width: 36,
                height: 36,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                cursor: "pointer",
              }}
            >
              <Icon path="M15 19l-7-7 7-7" color="#fff" size={20} />
            </button>
            <div>
              <div style={{ fontSize: 11, color: "rgba(255,255,255,0.75)" }}>
                대공원승무지회
              </div>
              <div style={{ fontSize: 20, fontWeight: 900, color: "#fff" }}>
                1:1 문의
              </div>
              <div
                style={{
                  fontSize: 11,
                  color: "rgba(255,255,255,0.7)",
                  marginTop: 4,
                }}
              >
                {isAdmin ? "전체 문의 관리 ·" : "나만 볼 수 있어요 ·"}{" "}
                <span style={{ color: "#C4B5FD", fontWeight: 700 }}>
                  {isAdmin ? "관리자 모드 ⚙️" : "편하게 물어보세요 🔒"}
                </span>
              </div>
            </div>
          </div>
          {user && !isAdmin && (
            <button
              onClick={onWrite}
              style={{
                background: "rgba(255,255,255,0.2)",
                border: "1.5px solid rgba(255,255,255,0.4)",
                borderRadius: 12,
                padding: "8px 16px",
                color: "#fff",
                fontSize: 13,
                fontWeight: 700,
                cursor: "pointer",
                fontFamily: "inherit",
                display: "flex",
                alignItems: "center",
                gap: 6,
              }}
            >
              <Icon path="M12 4v16m8-8H4" color="#fff" size={14} />
              문의작성
            </button>
          )}
        </div>
      </div>

      <div style={{ background: "#fff", marginTop: 8 }}>
        {inquiries.length === 0 && (
          <div
            style={{
              padding: "48px 20px",
              textAlign: "center",
              color: "#9CA3AF",
              fontSize: 14,
            }}
          >
            {isAdmin
              ? "들어온 문의가 없습니다"
              : "아직 문의 내역이 없습니다.\n궁금한 점을 편하게 남겨보세요"}
          </div>
        )}
        {inquiries.map((inq, i) => (
          <div
            key={inq.id}
            onClick={() => onSelect(inq)}
            style={{
              padding: "16px 20px",
              borderBottom:
                i < inquiries.length - 1 ? "1px solid #F3F4F6" : "none",
              cursor: "pointer",
            }}
          >
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 8,
                marginBottom: 6,
              }}
            >
              <span
                style={{
                  background: inq.status === "답변완료" ? "#D1FAE5" : "#FEF3C7",
                  color: inq.status === "답변완료" ? "#10B981" : "#F59E0B",
                  fontSize: 11,
                  fontWeight: 700,
                  borderRadius: 6,
                  padding: "2px 8px",
                  whiteSpace: "nowrap",
                }}
              >
                {inq.status}
              </span>
              <span
                style={{
                  fontSize: 15,
                  fontWeight: 600,
                  color: "#1F2937",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                  whiteSpace: "nowrap",
                }}
              >
                {inq.title}
              </span>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <span style={{ fontSize: 12, color: "#6B7280" }}>
                {inq.author}
              </span>
              <span style={{ fontSize: 12, color: "#D1D5DB" }}>·</span>
              <span style={{ fontSize: 12, color: "#9CA3AF" }}>
                {inq.created_at?.slice(0, 10)}
              </span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

