function VoteDetail({ vote, onBack, user }) {
  const optionLabels = Array.isArray(vote.options) ? vote.options : [];
  const colorPalette = [
    "#4F46E5",
    "#EF4444",
    "#10B981",
    "#F59E0B",
    "#0EA5E9",
    "#9CA3AF",
  ];
  const myId = String(user?.employee_number || user?.emp_id || user?.id || "");

  const [results, setResults] = useState([]);
  const [myVote, setMyVote] = useState(null);
  const [submitted, setSubmitted] = useState(false);
  const [voteSubmitting, setVoteSubmitting] = useState(false);
const [nameMap, setNameMap] = useState({});
  const loadResults = () => {
    supabase
      .from("vote_results")
      .select("choice, member_id")
      .eq("vote_id", vote.id)
      .then(({ data }) => {
        if (data) {
          setResults(data);
          const mine = data.find((r) => r.member_id === myId);
          if (mine) {
            setSubmitted(true);
          }
        }
      });
  };

  useEffect(() => {
    loadResults();
  }, [vote.id]);

  useEffect(() => {
    supabase
      .from("members")
      .select("employee_number, id, name")
      .then(({ data }) => {
        if (data) {
          const m = {};
          data.forEach((x) => {
            if (x.employee_number != null) m[String(x.employee_number)] = x.name;
            if (x.id != null) m[String(x.id)] = x.name;
          });
          setNameMap(m);
        }
      });
  }, []);

  const countOf = (label) => results.filter((r) => r.choice === label).length;
  const totalVotes = results.length;
  const getPercent = (label) =>
    totalVotes === 0 ? 0 : Math.round((countOf(label) / totalVotes) * 100);

  const handleVote = (idx) => {
    if (submitted || vote.status === "종료") return;
    setMyVote(idx);
  };

  const handleSubmit = async () => {
    if (voteSubmitting) return; // 연타 방지
    if (myVote === null) return;
    setVoteSubmitting(true);
    try {
      const choice = optionLabels[myVote];
      const { error } = await supabase
        .from("vote_results")
        .insert([{ vote_id: vote.id, member_id: myId, choice: choice }]);
      if (error) throw error;
      setSubmitted(true);
      addPoint(getUserId(user), "vote", "vote_" + vote.id); // 실제 제출 시에만 · 같은 투표 중복 방지
      loadResults();
    } catch (e: any) {
      showToast("투표 제출에 실패했습니다. 잠시 후 다시 시도해주세요.", "error");
      logError({
        message: "투표 제출 실패: " + (e?.message || String(e)),
        stack: e?.stack,
        screen: "투표참여",
        userId: getUserId(user),
        userName: user?.name,
      });
    } finally {
      setVoteSubmitting(false);
    }
  };
  const handleRevote = async () => {
    if (voteSubmitting) return;
    setVoteSubmitting(true);
    try {
      const { error } = await supabase
        .from("vote_results")
        .delete()
        .eq("vote_id", vote.id)
        .eq("member_id", myId);
      if (error) throw error;
      setSubmitted(false);
      setMyVote(null);
      loadResults();
    } catch (e: any) {
      showToast("재투표 처리에 실패했습니다. 잠시 후 다시 시도해주세요.", "error");
      logError({
        message: "재투표 실패: " + (e?.message || String(e)),
        stack: e?.stack,
        screen: "투표참여",
        userId: getUserId(user),
        userName: user?.name,
      });
    } finally {
      setVoteSubmitting(false);
    }
  };

  const showResult = vote.status === "종료";

  return (
    <div
      style={{
        maxWidth: 430,
        margin: "0 auto",
        fontFamily: "'Apple SD Gothic Neo', 'Noto Sans KR', sans-serif",
        background: "#F4F3FF",
        minHeight: "100vh",
        paddingBottom: 80,
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 12,
          padding: "56px 20px 16px",
          background: "#fff",
          borderBottom: "1px solid #F3F4F6",
        }}
      >
        <button
          onClick={onBack}
          style={{
            background: "none",
            border: "none",
            cursor: "pointer",
            padding: 4,
          }}
        >
          <Icon path="M15 19l-7-7 7-7" color="#1F2937" size={24} />
        </button>
        <span style={{ fontSize: 17, fontWeight: 700, color: "#1F2937" }}>
          {vote.type} 상세
        </span>
      </div>

      <div style={{ padding: "20px 16px" }}>
        <div
          style={{
            background: "#fff",
            borderRadius: 20,
            padding: "20px",
            marginBottom: 12,
            boxShadow: "0 2px 8px rgba(79,70,229,0.06)",
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 8,
              marginBottom: 12,
            }}
          >
            <span
              style={{
                background: vote.type === "투표" ? "#EEF0FF" : "#D1FAE5",
                color: vote.type === "투표" ? "#4F46E5" : "#10B981",
                fontSize: 11,
                fontWeight: 700,
                borderRadius: 6,
                padding: "3px 8px",
              }}
            >
              {vote.type}
            </span>
            <span
              style={{
                background: vote.status === "진행중" ? "#FEF3C7" : "#F3F4F6",
                color: vote.status === "진행중" ? "#F59E0B" : "#9CA3AF",
                fontSize: 11,
                fontWeight: 700,
                borderRadius: 6,
                padding: "3px 8px",
              }}
            >
              {vote.status}
            </span>
          </div>
          <div
            style={{
              fontSize: 17,
              fontWeight: 800,
              color: "#1F2937",
              marginBottom: 8,
              lineHeight: 1.4,
            }}
          >
            {vote.title}
          </div>
          <div
            style={{
              fontSize: 13,
              color: "#6B7280",
              lineHeight: 1.6,
              marginBottom: 12,
            }}
          >
            {vote.description}
          </div>
          <div style={{ display: "flex", gap: 16 }}>
            <div style={{ fontSize: 12, color: "#9CA3AF" }}>
              📅 마감:{" "}
              <strong style={{ color: "#374151" }}>
                {vote.deadline || "미정"}
              </strong>
            </div>
            <div style={{ fontSize: 12, color: "#9CA3AF" }}>
              👥 참여:{" "}
              <strong style={{ color: "#4F46E5" }}>{totalVotes}명</strong>
            </div>
          </div>
        </div>

        <div
          style={{
            background: "#fff",
            borderRadius: 20,
            padding: "20px",
            boxShadow: "0 2px 8px rgba(79,70,229,0.06)",
            marginBottom: 12,
          }}
        >
          <div
            style={{
              fontSize: 14,
              fontWeight: 700,
              color: "#1F2937",
              marginBottom: 16,
            }}
          >
            {showResult ? "결과" : "선택하세요"}
          </div>
          {optionLabels.map((label, i) => {
            const color = colorPalette[i % colorPalette.length];
            return (
              <div
                key={i}
                onClick={() => handleVote(i)}
                style={{
                  marginBottom: 12,
                  cursor: showResult ? "default" : "pointer",
                }}
              >
                <div
                  style={{
                    display: "flex",
                    justifyContent: "space-between",
                    marginBottom: 6,
                  }}
                >
                  <div
                    style={{ display: "flex", alignItems: "center", gap: 8 }}
                  >
                    {!showResult && (
                      <div
                        style={{
                          width: 18,
                          height: 18,
                          borderRadius: "50%",
                          border: `2px solid ${
                            myVote === i ? color : "#E5E7EB"
                          }`,
                          background: myVote === i ? color : "#fff",
                          flexShrink: 0,
                        }}
                      />
                    )}
                    <span
                      style={{
                        fontSize: 14,
                        fontWeight: myVote === i ? 700 : 400,
                        color: "#1F2937",
                      }}
                    >
                      {label}
                    </span>
                  </div>
                  {showResult && (
                    <span
                      style={{ fontSize: 13, fontWeight: 700, color: color }}
                    >
                      {getPercent(label)}%
                    </span>
                  )}
                </div>
                {showResult && (
                  <div
                    style={{
                      background: "#F3F4F6",
                      borderRadius: 10,
                      height: 8,
                      overflow: "hidden",
                    }}
                  >
                    <div
                      style={{
                        height: "100%",
                        background: color,
                        borderRadius: 10,
                        width: `${getPercent(label)}%`,
                        transition: "width 0.5s",
                      }}
                    />
                  </div>
                )}
                {showResult && !vote.is_anonymous && (
                  <div style={{ marginTop: 6, display: "flex", flexWrap: "wrap", gap: 4 }}>
                    {results
                      .filter((r) => r.choice === label)
                      .map((r, idx) => (
                        <span
                          key={idx}
                          style={{
                            fontSize: 11,
                            color: "#6B7280",
                            background: "#F3F4F6",
                            borderRadius: 6,
                            padding: "2px 8px",
                          }}
                        >
                          {nameMap[String(r.member_id)] || "알 수 없음"}
                        </span>
                      ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {!submitted && vote.status === "진행중" && user && (
          <button
            onClick={handleSubmit}
            disabled={myVote === null || voteSubmitting}
            style={{
              width: "100%",
              padding: "15px",
              background:
                myVote === null || voteSubmitting
                  ? "#E5E7EB"
                  : "linear-gradient(135deg, #4F46E5, #6D28D9)",
              color: myVote === null || voteSubmitting ? "#9CA3AF" : "#fff",
              border: "none",
              borderRadius: 14,
              fontSize: 16,
              fontWeight: 700,
              cursor: myVote === null || voteSubmitting ? "not-allowed" : "pointer",
              fontFamily: "inherit",
            }}
          >
            {voteSubmitting ? "제출 중..." : `${vote.type} 참여하기`}
          </button>
        )}
        {submitted && (
          <div>
            <div
              style={{
                background: "#D1FAE5",
                borderRadius: 14,
                padding: "14px",
                textAlign: "center",
                fontSize: 14,
                fontWeight: 700,
                color: "#10B981",
                marginBottom: 10,
              }}
            >
              ✅ 참여 완료! 결과는 투표 마감 후 공개됩니다.
            </div>
            <div
              style={{
                background: "#F9FAFB",
                borderRadius: 12,
                padding: "12px 14px",
                fontSize: 12,
                color: "#6B7280",
                lineHeight: 1.7,
                marginBottom: 10,
              }}
            >
              🔒 공정한 투표를 위해 진행 중에는 결과를 공개하지 않습니다. 중간 현황이 보이면 소신과 다르게 분위기에 휩쓸릴 수 있어, 마감 후 한 번에 공개합니다.
            </div>
            {vote.status === "진행중" && (
              <button
                onClick={handleRevote}
                style={{
                  width: "100%",
                  padding: "13px",
                  background: "#fff",
                  color: "#4F46E5",
                  border: "1.5px solid #C7D2FE",
                  borderRadius: 14,
                  fontSize: 14,
                  fontWeight: 700,
                  cursor: "pointer",
                  fontFamily: "inherit",
                }}
              >
                🔄 다시 선택하기
              </button>
            )}
          </div>
        )}
        {vote.status === "종료" && !submitted && (
          <div
            style={{
              background: "#F3F4F6",
              borderRadius: 14,
              padding: "14px",
              textAlign: "center",
              fontSize: 14,
              color: "#9CA3AF",
            }}
          >
            종료된 {vote.type}입니다.
          </div>
        )}
        {!user && vote.status === "진행중" && (
          <div
            style={{
              background: "#FEF3C7",
              borderRadius: 14,
              padding: "14px",
              textAlign: "center",
              fontSize: 13,
              color: "#F59E0B",
            }}
          >
            로그인 후 참여할 수 있습니다.
          </div>
        )}
      </div>
    </div>
  );
}

function VoteScreen({ onBack, user }) {
  const [filter, setFilter] = useState("전체");
  const [selectedVote, setSelectedVote] = useState(null);
  // ── 뒤로가기: 투표 상세 → 목록 ──
  useEffect(() => {
    (window as any).__backHandler = () => {
      if (selectedVote) { setSelectedVote(null); return true; }
      return false;
    };
    return () => { (window as any).__backHandler = null; };
  });
  const [votes, setVotes] = useState([]);
  const [editVote, setEditVote] = useState(null);
  const [voteSaving, setVoteSaving] = useState(false);
  const isAdmin = user?.is_admin;
   const [myVotedIds, setMyVotedIds] = useState([]);
  const loadMyVotes = () => {
const myId = String(user?.employee_number || user?.emp_id || user?.id || "");
    if (!myId) return;
    supabase
      .from("vote_results")
      .select("vote_id")
      .eq("member_id", myId)
      .then(({ data }) => {
        if (data) setMyVotedIds(data.map((r) => r.vote_id));
      });
  };
  useEffect(() => {
    loadMyVotes();
  }, [user]);

  const loadVotes = () => {
    supabase
      .from("votes")
      .select("*")
      .order("created_at", { ascending: false })
      .then(({ data }) => {
        if (data) setVotes(data);
      });
  };

  useEffect(() => {
    loadVotes();
  }, []);

  const handleSaveVote = async () => {
    if (voteSaving) return; // 연타 방지
    if (!editVote.title.trim()) {
      showToast("제목을 입력해주세요.");
      return;
    }
    setVoteSaving(true);
    try {
      const { error } = await supabase
        .from("votes")
        .update({
          title: editVote.title,
          description: editVote.description,
          deadline: editVote.deadline || null,
          status: editVote.status,
        })
        .eq("id", editVote.id);
      if (error) throw error;
      setEditVote(null);
      loadVotes();
      showToast("저장되었습니다.");
    } catch (e: any) {
      showToast("저장에 실패했습니다. 잠시 후 다시 시도해주세요.", "error");
      logError({
        message: "투표 저장 실패: " + (e?.message || String(e)),
        stack: e?.stack,
        screen: "투표관리",
        userId: getUserId(user),
        userName: user?.name,
      });
    } finally {
      setVoteSaving(false);
    }
  };

  const handleDeleteVote = async (id) => {
    try {
      // 투표 결과 먼저 삭제 후 투표 본문 삭제
      const { error: e1 } = await supabase
        .from("vote_results")
        .delete()
        .eq("vote_id", id);
      if (e1) throw e1;
      const { error: e2 } = await supabase.from("votes").delete().eq("id", id);
      if (e2) throw e2;
      loadVotes();
      loadMyVotes();
    } catch (e: any) {
      showToast("삭제에 실패했습니다. 잠시 후 다시 시도해주세요.", "error");
      logError({
        message: "투표 삭제 실패: " + (e?.message || String(e)),
        stack: e?.stack,
        screen: "투표관리",
        userId: getUserId(user),
        userName: user?.name,
      });
    }
  };

  if (selectedVote) {
    return (
      <VoteDetail
        vote={selectedVote}
          onBack={() => {
          setSelectedVote(null);
          loadVotes();
          loadMyVotes();
        }}

        user={user}
      />
    );
  }

  const filtered =
    filter === "전체"
      ? votes
      : votes.filter((v) => v.type === filter || v.status === filter);

  return (
    <div
      style={{
        maxWidth: 430,
        margin: "0 auto",
        fontFamily: "'Apple SD Gothic Neo', 'Noto Sans KR', sans-serif",
        background: "#F4F3FF",
        minHeight: "100vh",
        paddingBottom: 80,
      }}
    >
      <div
        style={{
          background:
            "linear-gradient(135deg, #3730A3 0%, #4F46E5 50%, #6D28D9 100%)",
          padding: "52px 20px 24px",
          borderRadius: 28,
          position: "sticky",
          top: 0,
          zIndex: 50,
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 12,
            marginBottom: 16,
          }}
        >
          <button
            onClick={onBack}
            style={{
              background: "rgba(255,255,255,0.15)",
              border: "none",
              borderRadius: "50%",
              width: 36,
              height: 36,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              cursor: "pointer",
            }}
          >
            <Icon path="M15 19l-7-7 7-7" color="#fff" size={20} />
          </button>
          <div>
            <div style={{ fontSize: 11, color: "rgba(255,255,255,0.75)" }}>
              대공원승무지회
            </div>
            <div style={{ fontSize: 20, fontWeight: 900, color: "#fff" }}>
              투표/설문
            </div>
            <div
              style={{
                fontSize: 11,
                color: "rgba(255,255,255,0.7)",
                marginTop: 4,
              }}
            >
              당신의 한 표가 ·{" "}
              <span style={{ color: "#C4B5FD", fontWeight: 700 }}>
                변화를 만듭니다 🗳️
              </span>
            </div>
          </div>
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          {["전체", "투표", "설문", "진행중", "종료"].map((f) => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              style={{
                padding: "6px 12px",
                borderRadius: 20,
                border: "none",
                cursor: "pointer",
                fontFamily: "inherit",
                background: filter === f ? "#fff" : "rgba(255,255,255,0.15)",
                color: filter === f ? "#4F46E5" : "#fff",
                fontWeight: filter === f ? 700 : 400,
                fontSize: 12,
              }}
            >
              {f}
            </button>
          ))}
        </div>
      </div>

      <div style={{ padding: "12px 16px" }}>
        {filtered.map((vote) => (
          <div
            key={vote.id}
            style={{
              background: "#fff",
              borderRadius: 16,
              padding: "18px 20px",
              marginBottom: 10,
              boxShadow: "0 2px 8px rgba(79,70,229,0.06)",
            }}
          >
            <div
              onClick={() => setSelectedVote(vote)}
              style={{ cursor: "pointer" }}
            >
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                  marginBottom: 10,
                }}
              >
                <span
                  style={{
                    background: vote.type === "투표" ? "#EEF0FF" : "#D1FAE5",
                    color: vote.type === "투표" ? "#4F46E5" : "#10B981",
                    fontSize: 11,
                    fontWeight: 700,
                    borderRadius: 6,
                    padding: "3px 8px",
                  }}
                >
                  {vote.type}
                </span>
                <span
                  style={{
                    background:
                      vote.status === "진행중" ? "#FEF3C7" : "#F3F4F6",
                    color: vote.status === "진행중" ? "#F59E0B" : "#9CA3AF",
                    fontSize: 11,
                    fontWeight: 700,
                    borderRadius: 6,
                    padding: "3px 8px",
                  }}
                >
                  {vote.status}
                </span>
                <span
                  style={{
                    marginLeft: "auto",
                    fontSize: 12,
                    color: "#9CA3AF",
                  }}
                >
                  ~ {vote.deadline || "미정"}
                </span>
              </div>
              <div
                style={{
                  fontSize: 15,
                  fontWeight: 700,
                  color: "#1F2937",
                  marginBottom: 4,
                  lineHeight: 1.4,
                }}
              >
                {vote.title}
              </div>
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                  fontSize: 12,
                  color: "#9CA3AF",
                }}
              >
                <span>
                  {vote.status === "진행중"
                    ? "참여하려면 눌러주세요"
                    : "결과를 보려면 눌러주세요"}
                </span>
                <span
                  style={{
                    fontSize: 11,
                    fontWeight: 700,
                    color: myVotedIds.includes(vote.id)
                      ? "#16A34A"
                      : "#DC2626",
                  }}
                >
                  {myVotedIds.includes(vote.id) ? "✓ 참여함" : "미참여"}
                </span>
              </div>
            </div>
            {isAdmin && (
              <div
                style={{
                  display: "flex",
                  gap: 8,
                  marginTop: 12,
                  paddingTop: 12,
                  borderTop: "1px solid #F3F4F6",
                }}
              >
                <button
                  onClick={() => setEditVote(vote)}
                  style={{
                    flex: 1,
                    padding: "8px",
                    borderRadius: 8,
                    border: "none",
                    background: "#F3F4F6",
                    color: "#6B7280",
                    fontSize: 13,
                    fontWeight: 700,
                    cursor: "pointer",
                    fontFamily: "inherit",
                  }}
                >
                  수정
                </button>
                <button
                  onClick={() => {
                    if (
                      window.confirm(
                        "이 투표를 삭제할까요? 투표 결과도 함께 삭제됩니다."
                      )
                    )
                      handleDeleteVote(vote.id);
                  }}
                  style={{
                    flex: 1,
                    padding: "8px",
                    borderRadius: 8,
                    border: "none",
                    background: "#FEE2E2",
                    color: "#EF4444",
                    fontSize: 13,
                    fontWeight: 700,
                    cursor: "pointer",
                    fontFamily: "inherit",
                  }}
                >
                  삭제
                </button>
              </div>
            )}
          </div>
        ))}
        {editVote && (
          <div
            style={{
              position: "fixed",
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              background: "rgba(0,0,0,0.4)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              zIndex: 1000,
              padding: 20,
            }}
            onClick={() => setEditVote(null)}
          >
            <div
              onClick={(e) => e.stopPropagation()}
              style={{
                background: "#fff",
                borderRadius: 20,
                padding: "24px 20px",
                width: "100%",
                maxWidth: 360,
              }}
            >
              <div
                style={{
                  fontSize: 17,
                  fontWeight: 800,
                  color: "#1F2937",
                  marginBottom: 18,
                }}
              >
                투표 수정
              </div>
              <div style={{ fontSize: 12, color: "#6B7280", marginBottom: 6 }}>
                제목
              </div>
              <input
                value={editVote.title}
                onChange={(e) =>
                  setEditVote({ ...editVote, title: e.target.value })
                }
                style={{
                  width: "100%",
                  padding: "11px 12px",
                  borderRadius: 10,
                  border: "1.5px solid #E5E7EB",
                  fontSize: 14,
                  outline: "none",
                  boxSizing: "border-box",
                  fontFamily: "inherit",
                  marginBottom: 14,
                }}
              />
              <div style={{ fontSize: 12, color: "#6B7280", marginBottom: 6 }}>
                설명
              </div>
              <textarea
                value={editVote.description || ""}
                onChange={(e) =>
                  setEditVote({ ...editVote, description: e.target.value })
                }
                rows={3}
                style={{
                  width: "100%",
                  padding: "11px 12px",
                  borderRadius: 10,
                  border: "1.5px solid #E5E7EB",
                  fontSize: 14,
                  outline: "none",
                  boxSizing: "border-box",
                  fontFamily: "inherit",
                  marginBottom: 14,
                  resize: "none",
                }}
              />
              <div style={{ fontSize: 12, color: "#6B7280", marginBottom: 6 }}>
                마감일
              </div>
              <input
                type="date"
                value={editVote.deadline || ""}
                onChange={(e) =>
                  setEditVote({ ...editVote, deadline: e.target.value })
                }
                style={{
                  width: "100%",
                  padding: "11px 12px",
                  borderRadius: 10,
                  border: "1.5px solid #E5E7EB",
                  fontSize: 14,
                  outline: "none",
                  boxSizing: "border-box",
                  fontFamily: "inherit",
                  marginBottom: 14,
                }}
              />
              <div style={{ fontSize: 12, color: "#6B7280", marginBottom: 6 }}>
                상태
              </div>
              <div style={{ display: "flex", gap: 8, marginBottom: 20 }}>
                {["진행중", "종료"].map((s) => (
                  <button
                    key={s}
                    onClick={() => setEditVote({ ...editVote, status: s })}
                    style={{
                      flex: 1,
                      padding: "10px",
                      borderRadius: 10,
                      border:
                        editVote.status === s
                          ? "1.5px solid #4F46E5"
                          : "1.5px solid #E5E7EB",
                      background: editVote.status === s ? "#EEF0FF" : "#fff",
                      color: editVote.status === s ? "#4F46E5" : "#9CA3AF",
                      fontSize: 14,
                      fontWeight: 700,
                      cursor: "pointer",
                      fontFamily: "inherit",
                    }}
                  >
                    {s}
                  </button>
                ))}
              </div>
              <div style={{ display: "flex", gap: 10 }}>
                <button
                  onClick={() => setEditVote(null)}
                  style={{
                    flex: 1,
                    padding: "12px",
                    borderRadius: 10,
                    border: "1.5px solid #E5E7EB",
                    background: "#fff",
                    color: "#6B7280",
                    fontSize: 14,
                    fontWeight: 700,
                    cursor: "pointer",
                    fontFamily: "inherit",
                  }}
                >
                  취소
                </button>
                <button
                  onClick={handleSaveVote}
                  disabled={voteSaving}
                  style={{
                    flex: 1,
                    padding: "12px",
                    borderRadius: 10,
                    border: "none",
                    background: voteSaving
                      ? "#A5B4FC"
                      : "linear-gradient(135deg, #4F46E5, #6D28D9)",
                    color: "#fff",
                    fontSize: 14,
                    fontWeight: 700,
                    cursor: voteSaving ? "default" : "pointer",
                    fontFamily: "inherit",
                  }}
                >
                  {voteSaving ? "저장 중..." : "저장"}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

