  const [tempPasswords, setTempPasswords] = useState({});

  const handleApprove = (id) => {
    const tempPw = generateTempPassword();
    const target = pendingMembers.find((m) => m.id === id);
   const emp = target && ((target as any).employee_number || (target as any).emp_id || (target as any).id);
    setTempPasswords((prev) => ({ ...prev, [id]: tempPw }));
    setPendingMembers((prev) =>
      prev.map((m) =>
        m.id === id
          ? {
              ...m,
              status: "approved",
              is_temp_password: true,
            }
          : m
      )
    );
    supabase
      .from("members")
      .update({ status: "approved" })
      .eq("id", id)
      .then(() => {
        fetch("/.netlify/functions/set-credential", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            employee_number: emp,
            password: tempPw,
            is_temp_password: true,
          }),
        });
      });
  };
  const handleBlock = (id) => {
    setPendingMembers((prev) =>
      prev.map((m) => (m.id === id ? { ...m, status: "blocked" } : m))
    );
  };
  const handleKick = (id) => {
    setPendingMembers((prev) =>
      prev.map((m) => (m.id === id ? { ...m, status: "kicked" } : m))
    );
  };

