    const wtSetting = worktypeSettings.find((w) => w.work_type === workType);
    const rate = (wtSetting && wtSetting.bojeon_rate != null) ? Number(wtSetting.bojeon_rate) : (rates[workType] ?? 0);
    return Math.round(basicSalary * rate);
